local UISwitchImage = CS.Game.Native.Common.UISwitchImage
local ImageAlterable = CS.Engine.UI.ImageAlterable
local Image = CS.UnityEngine.UI.Image
local UIEventProxy = CS.Engine.UI.UIEventProxy
local cs_coroutine = require("XLua.cs_coroutine")
local SkeletonGraphic = CS.Spine.Unity.SkeletonGraphic
local GameObject = CS.UnityEngine.GameObject
------------ import ------------

------------ define ------------
local ROOT_NAME_BUBBLE = "ImgFrame"
local ROOT_NAME_EMOJI = "EmojiNode"
local ROOT_NAME_EMOJI_DYNAMIC = "EmojiNodeDynamic"
local ROOT_NAME_LOCK = "ImgLock"
local TYPE_BUBBLE = {
    LIST_ITEM = 1,  -- 解锁的底板
    OUR = 2,        -- 我方气泡底板
    ENEMY = 3,      -- 敌方气泡底板
    LOCK = 4,       -- 未解锁的底板
}
local TYPE_EMOJI_IMG = {
    UNLOCK = 1,     -- 解锁
    LOCK = 2        -- 未解锁
}
------------ define ------------

---@class CommonEmojiNode
local CommonEmojiNode = Class('CommonEmojiNode')

------------ lifeCycle ------------
function CommonEmojiNode:__init()
    self.switchBubble = nil     -- 背景气泡的 switchImg 组件
    self.switchEmojiImg = nil       -- 静态表情图片的 switchImg 组件
    self.imgAlter = nil         -- 静态表情的 ImgAlter 组件
    self.skeletonGraphic = nil  -- 动态表情的 skeletonGraphic 组件
    self.goImgEmoji = nil          -- 静态表情的 gameobject
    self.goSpineEmoji = nil   -- 动态表情的 gameobject
    self.goLock = nil           -- 锁的 gameobject
    self.spineEmojiPrefabList = nil -- 缓存spine表情的go
end

function CommonEmojiNode:__delete()
    self.switchBubble = nil
    self.switchEmojiImg = nil
    self.imgAlter = nil
    self.skeletonGraphic = nil
    self.goImgEmoji = nil
    self.goSpineEmoji = nil
    self.goLock = nil
    self.spineEmojiPrefabList = nil
end

function CommonEmojiNode:Awake()
    self:InitComp()
end

function CommonEmojiNode:Start()
end

function CommonEmojiNode:OnDestroy()
    if self.spineEmojiPrefabList then
        for i, v in pairs(self.spineEmojiPrefabList) do
            GameObject.Destroy(v)
        end
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------

------------ init ------------
function CommonEmojiNode:InitComp()
    local transBGBubble = self.controller.transform:Find(ROOT_NAME_BUBBLE)
    if not IsNull(transBGBubble) then
        self.switchBubble = transBGBubble.gameObject:GetComponent(typeof(UISwitchImage))
    end
    local transLock = self.controller.transform:Find(ROOT_NAME_LOCK)
    if not IsNull(transLock) then
        self.goLock = transLock.gameObject
    end
    local transEmoji = self.controller.transform:Find(ROOT_NAME_EMOJI)
    if not IsNull(transEmoji) then
        self.goImgEmoji = transEmoji.gameObject
        self.imgAlter = transEmoji.gameObject:GetComponent(typeof(ImageAlterable))
        self.switchEmojiImg = transEmoji.gameObject:GetComponent(typeof(UISwitchImage))
    end
    local transEmojiDynamic = self.controller.transform:Find(ROOT_NAME_EMOJI_DYNAMIC)
    if not IsNull(transEmojiDynamic) then
        self.goSpineEmoji = transEmojiDynamic.gameObject
        self.skeletonGraphic = transEmojiDynamic.gameObject:GetComponent(typeof(SkeletonGraphic))
    end
end
------------ init ------------

--- 设置气泡框的箭头方向
---@param numType integer 枚举类型
function CommonEmojiNode:SetBGBubbleState(numType)
    if IsNull(self.switchBubble) then return end
    self.switchBubble.Status = numType
    self.switchBubble:Reset()
end

--- 设置表情菜单里的表情是否是锁定的状态
---@param state integer 
function CommonEmojiNode:SetEmojiImgState(state)
    if isNull(self.switchEmojiImg) then return end
    self.switchEmojiImg.Status = state
    self.switchEmojiImg:Reset()
end

--- 设置锁头图片的显隐状态
---@param state any
function CommonEmojiNode:SetLockActive(state)
    if isNull(self.goLock) then return end
    CS.Engine.Lib.KTool.SetActive(self.goLock, state)
end

--- 给图片组件设置资源
---@param resPath string @ 资源路径
function CommonEmojiNode:SetEmojiRawImg(resPath)
    if IsNull(self.imgAlter) then return end
    if isNull(UIBattlingPVPMgr) then return end

    CfUtils.FillImage(self.imgAlter, resPath)
end

--- 给spine组件设置资源
---@param resPath string @ 资源路径
function CommonEmojiNode:SetEmojiSkeletonGraphic(resPath)
    if IsNull(self.skeletonGraphic) then return end
    if isNull(UIBattlingPVPMgr) then return end
    self.spineEmojiPrefabList = checkTable(self.spineEmojiPrefabList)
    local outData = {skeletonDataAsset = nil}
    cs_coroutine.yield_return(GameUtils.GetSpineEmojiData(resPath, outData, true, self.spineEmojiPrefabList))
    if IsNull(outData.skeletonDataAsset) then return end
    self:ReloadSpine(self.skeletonGraphic, outData.skeletonDataAsset)
end

--- 设置表情列表
function CommonEmojiNode:SetEmojiListItem(emojiData)
    self:SetUseStatic()
    self:SetEmojiRawImg(emojiData.vo.photoPath)
    if emojiData.unlock then
        self:SetBGBubbleState(TYPE_BUBBLE.LIST_ITEM)
        self:SetEmojiImgState(TYPE_EMOJI_IMG.UNLOCK)
        self:SetLockActive(false)
        UIEventProxy.Create(self.goImgEmoji).onPointerClick = function()
            --TODO广播事件
            Events.Broadcast(Constants.EventNames.UIBattlingSelectEmoji, emojiData.vo.id)
        end
    else
        self:SetBGBubbleState(TYPE_BUBBLE.LOCK)
        self:SetEmojiImgState(TYPE_EMOJI_IMG.LOCK)
        self:SetLockActive(true)
    end
end

--- 设置节点的激活状态
---@param showState boolean @ 显示状态
function CommonEmojiNode:SetNodeActive(showState)
    if IsNull(self.controller) or IsNull(self.controller.gameObject) then return end
    CS.Engine.Lib.KTool.SetActive(self.controller.gameObject, showState)
end

--- 设置为使用静态表情
function CommonEmojiNode:SetUseStatic()
    CS.Engine.Lib.KTool.SetActive(self.goImgEmoji, true)
    CS.Engine.Lib.KTool.SetActive(self.goSpineEmoji, false)
end

--- 设置为使用动态表情
function CommonEmojiNode:SetUseDynamic()
    CS.Engine.Lib.KTool.SetActive(self.goImgEmoji, false)
    CS.Engine.Lib.KTool.SetActive(self.goSpineEmoji, true)
end

--- 重载spine动画
---@param skeletonGraphic Spine.Unity.SkeletonGraphic @ spine组件
---@param skeletonDataAsset Spine.Unity.SkeletonGraphic @ spine资源
function CommonEmojiNode:ReloadSpine(skeletonGraphic, skeletonDataAsset)
    skeletonGraphic.skeletonDataAsset = skeletonDataAsset
    skeletonGraphic:Initialize(true)
    -- skeletonGraphic:LateUpdate()
end

return CommonEmojiNode